/* @autogenerated */
import { signal } from '@angular/core';
import { ComponentFixture, TestBed } from '@angular/core/testing';
import { Router } from '@angular/router';
import { ToolbarComponent } from './toolbar.component';
import { IdentityService } from '@shared/context/identity/identity.service';
import { AppStateService, ContextValue } from '@shared/context/state/app-state.service';
import { RuntimeConfigService } from '@shared/context/config/app-config.service';
import { WorkspaceStateService } from 'app/bootstrap/workspace/workspace-state.service';
import { UserMenuItem } from 'app/bootstrap/workspace/workspace.model';

describe('ToolbarComponent', () => {
  let fixture: ComponentFixture<ToolbarComponent>;
  let component: ToolbarComponent;
  let identityMock: any;
  let routerMock: any;
  let userMenu: ReturnType<typeof signal<UserMenuItem[]>>;
  let contexts: ReturnType<typeof signal<Record<string, ContextValue | null>>>;

  beforeEach(async () => {
    identityMock = {
      login: jasmine.createSpy('login'),
      logout: jasmine.createSpy('logout'),
    };
    routerMock = { navigate: jasmine.createSpy('navigate') };
    userMenu = signal<UserMenuItem[]>([]);
    contexts = signal<Record<string, ContextValue | null>>({});

    await TestBed.configureTestingModule({
      imports: [ToolbarComponent],
      providers: [
        { provide: IdentityService, useValue: identityMock },
        { provide: Router, useValue: routerMock },
        {
          provide: AppStateService,
          useValue: { language: signal('es'), tenant: signal('main'), contexts },
        },
        {
          provide: WorkspaceStateService,
          useValue: {
            userMenu,
            link: (route?: string, workspace?: string) => ['/', 'es', 'main', workspace ?? 'here', route ?? ''],
          },
        },
        {
          provide: RuntimeConfigService,
          useValue: { value: (path: string) => signal(path === 'meta.title' ? 'phylax' : undefined) },
        },
      ],
    })
      .overrideComponent(ToolbarComponent, {
        set: { template: '' },
      })
      .compileComponents();

    fixture = TestBed.createComponent(ToolbarComponent);
    component = fixture.componentInstance;
  });

  it('offers the options of the active workspace whose required selectors have a value', () => {
    userMenu.set([
      { label: 'Admin', workspace: '@admin' },
      { label: 'Client report', route: 'report', requires: ['client'] },
    ]);
    expect(component.workspaceItems().map((item) => item.label)).toEqual(['Admin']);

    contexts.set({ client: ContextValue.fixed('client', { $ref: 'c1' }, 'client') });
    expect(component.workspaceItems().map((item) => item.label)).toEqual(['Admin', 'Client report']);
  });

  it('opens a route of the workspace or another workspace', () => {
    component.open({ label: 'Report', route: 'report' });
    expect(routerMock.navigate).toHaveBeenCalledWith(['/', 'es', 'main', 'here', 'report']);

    component.open({ label: 'Admin', workspace: 'admin' });
    expect(routerMock.navigate).toHaveBeenCalledWith(['/', 'es', 'main', 'admin', '']);
  });

  it('emits menuClicked event on toggle', () => {
    let called = false;
    component.menuClicked.subscribe(() => (called = true));

    component.toogleMenu();

    expect(called).toBeTrue();
  });

  it('delegates login and logout to IdentityService', () => {
    component.login();
    component.logout();

    expect(identityMock.login).toHaveBeenCalledWith('main');
    expect(identityMock.logout).toHaveBeenCalledWith('main');
  });
});
